using System;
using System.IO;
using System.Runtime.Serialization.Json;
using System.Threading.Tasks;
using RichAudio.GeometryResearch;
public static class TestGeometryObservation
{
    private static int checks;
    private static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
    private static GeometryObservation Hit(){return new GeometryObservation{SessionId="original-synthetic",GameVersion="1.0.1158.16",FrameworkVersion="1.132.1428.17748",Origin=new Point3(0,0,1),End=new Point3(8,0,1),HitPosition=new Point3(4,0,1),HitNormal=new Point3(-1,0,0),Completion="hit",TraceCalls=1,IgnoredPlayerHandle=123,PositionStatus="observed",NormalStatus="observed",EntityStatus="none_returned_static_unproven",ObservedAtMs=100,TraceDurationMs=.2,ConversionDurationMs=.1,SetupStatus="on_foot_stationary_by_SDK_getters",PlayerSpeed=0};}
    private static void Reject(Action<GeometryObservation> edit,string name){var r=Hit();edit(r);Check(!ObservationRules.Validate(r).SurfaceValid,name);}
    public static int Main(string[] args)
    {
        try{
            var record=Hit();var v=ObservationRules.Validate(record);Check(v.RecordValid&&v.SurfaceValid,"valid hit");Check(v.SegmentParameter==.5,"analytic midpoint");Check(v.OffSegmentDistance==0,"analytic ray membership");Check(v.NormalLength==1,"unit normal");Check(v.NormalRayDot==-1&&v.NormalOrientation=="against_ray","orientation recorded");Check(v.WallLike==true&&v.NonGrazing==true,"wall-like classification");
            var reverse=Hit();reverse.HitNormal=new Point3(1,0,0);Check(ObservationRules.Validate(reverse).SurfaceValid,"do not assume vendor normal sign");Check(ObservationRules.Validate(reverse).NormalOrientation=="with_ray","reverse sign retained");
            var floor=Hit();floor.HitNormal=new Point3(0,0,1);Check(ObservationRules.Validate(floor).WallLike==false,"a floor is not the intended wall");Check(ObservationRules.Validate(floor).TargetIdentity=="requires_supervised_confirmation","no fabricated target identification");
            var miss=Hit();miss.Completion="miss";miss.HitPosition=null;miss.HitNormal=null;Check(ObservationRules.Validate(miss).RecordValid&&!ObservationRules.Validate(miss).SurfaceValid,"valid miss, no surface");Reject(r=>r.Completion="pending","incomplete");Reject(r=>r.Completion="error","exception");Reject(r=>r.HitPosition=null,"missing position");Reject(r=>r.HitNormal=null,"missing normal");
            foreach(double x in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity}){Reject(r=>r.HitPosition=new Point3(x,0,1),"nonfinite hit");Reject(r=>r.HitNormal=new Point3(x,0,0),"nonfinite normal");Reject(r=>r.ObservedAtMs=x,"nonfinite time");Reject(r=>r.MaximumDistance=x,"nonfinite length");}
            Reject(r=>r.HitNormal=new Point3(0,0,0),"zero normal");Reject(r=>r.HitNormal=new Point3(2,0,0),"nonunit normal");Reject(r=>r.HitPosition=new Point3(9,0,1),"past endpoint");Reject(r=>r.HitPosition=new Point3(-1,0,1),"behind origin");Reject(r=>r.HitPosition=new Point3(4,.1,1),"off line");Reject(r=>r.End=r.Origin,"zero trace");Reject(r=>r.MaximumDistance=0,"zero maximum");Reject(r=>r.MaximumDistance=11,"unbounded trace");
            Reject(r=>r.SessionId="","missing session");Reject(r=>r.SessionId="private/path","invalid session");Reject(r=>r.GameVersion=null,"missing build");Reject(r=>r.GameVersion="1.0.1158.13","wrong build");Reject(r=>r.FrameworkVersion="unverified","wrong framework");Reject(r=>r.CoordinateSpace="claimed-metres","unverified conversion");Reject(r=>r.TimeUnit="seconds","time units");Reject(r=>r.TraceCalls=2,"query count");Reject(r=>r.FlagsValue=511,"world-only scope");Reject(r=>r.IgnoredPlayerHandle=null,"ignored entity unavailable");
            Reject(r=>r.PlayerSpeed=.26,"moving player");Reject(r=>r.PlayerSpeed=null,"missing speed");Reject(r=>r.PlayerSpeed=double.NaN,"invalid speed");Reject(r=>r.SetupStatus="in-vehicle","wrong setup");
            Reject(r=>{r.HitEntityHandle=9;r.EntityStatus="static-building-guessed";},"ambiguous identity");Reject(r=>{r.HitEntityHandle=0;r.EntityStatus="returned_identity_unclassified";},"invalid handle");Reject(r=>r.EntityStatus="returned_invalid_identity","invalid returned identity");Reject(r=>r.MaterialStatus="concrete-guessed","invented material");Reject(r=>r.ExtentStatus="complete-wall","invented extent");
            Check(ObservationRules.Fresh(record,record.SessionId,record.GameVersion,200,500),"fresh same session");Check(!ObservationRules.Fresh(record,record.SessionId,record.GameVersion,900,500),"stale");Check(!ObservationRules.Fresh(record,"different",record.GameVersion,200,500),"wrong session");Check(!ObservationRules.Fresh(record,record.SessionId,"different",200,500),"wrong build cache");Check(!ObservationRules.Fresh(record,record.SessionId,record.GameVersion,99,500),"clock reset");Check(!ObservationRules.Fresh(record,record.SessionId,record.GameVersion,200,2000),"unbounded cache TTL");
            var point=ObservationRules.Retain(record);Check(point.Width==null&&point.Height==null,"extent remains unknown");Check(point.AcousticEnergyReflectance==null&&point.Material=="unknown","material remains unknown");Check(point.StaticClassification=="unverified","absent entity not permanence");Check(point.Provenance==record.QueryProvenance&&point.Position.X==4,"provenance and point copied");Check(point.CoordinateSpace=="gta-native-units-unverified","coordinate hypothesis preserved");
            bool failed=false;try{ObservationRules.Retain(miss);}catch(InvalidDataException){failed=true;}Check(failed,"no retained surface on miss");
            var gate=new OneObservationGate();int calls=0;Parallel.For(0,32,i=>{if(gate.TryClaim())System.Threading.Interlocked.Increment(ref calls);});Check(calls==1&&gate.Claims==1,"atomic one-call bound");gate.Finish();Check(gate.IsFinished&&!gate.TryClaim(),"observer disables after result");var cancelled=new OneObservationGate();cancelled.Finish();Check(!cancelled.TryClaim()&&cancelled.Claims==0,"shutdown without capture");
            string dir=Path.GetFullPath(args[0]);Directory.CreateDirectory(dir);string marker=Path.Combine(dir,"owned-test.attempt");DurableAttempt.Reserve(marker,"synthetic");string saved=File.ReadAllText(marker);failed=false;try{DurableAttempt.Reserve(marker,"second");}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(marker)==saved,"reload reservation rejects overwrite");File.Delete(marker);Check(!File.Exists(marker),"owned synthetic reservation cleanup verified");
            using(var stream=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(GeometryObservation));serializer.WriteObject(stream,record);File.WriteAllBytes(Path.Combine(dir,"synthetic-hit.json"),stream.ToArray());stream.Position=0;var roundtrip=(GeometryObservation)serializer.ReadObject(stream);Check(ObservationRules.Validate(roundtrip).SurfaceValid,"JSON roundtrip");Check(roundtrip.QueryProvenance==record.QueryProvenance&&roundtrip.HitEntityHandle==null,"missing fields and provenance roundtrip");}
            Console.WriteLine("PASS: "+checks+" synthetic geometry-observation assertions; no game or SDK execution.");return 0;
        }catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}
    }
}
